head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


urlHdr = "/listingCommon.do?method=listGeneral";
svcId = "service=krx.lds.stf.listingcommon.services.ListingCommonApp";
reqInf = [{
    id: "200",
    mkt: "2",
    def: [{
        msgId: "GENDISCLS_DELIST_K_INOUT",
        qryId: "lds.stf.lstproc.marketaction.delist.k.select"
    }, {
        msgId: "GENDISCLS_DELIST_K_DTL_INOUT",
        qryId: "lds.stf.lstproc.marketaction.delist.k.dtl.select"
    }]
}, {
    id: "230", // 업종변경(유)	
    mkt: "1",
    def: [{
        msgId: "GENDISCLS_INDCHG_I_INOUT",
        qryId: "lds.stf.lstproc.marketaction.indchg.i.select"
    }]
}, {
    id: "230", // 업종변경(코)	
    mkt: "2",
    def: [{
        msgId: "GENDISCLS_INDCHG_K_INOUT",
        qryId: "lds.stf.lstproc.marketaction.indchg.k.select"
    }]
}];
isuInf = [{
    id: "200",
    mkt: "2",
    msgId: "GENDISCLS_DELIST_INOUT",
    qryId: "lds.stf.lstproc.marketaction.delist.i.isu.select"
}];
urlFtr = "{P}BZ_PROCS_NO=";
/**
 * @method
 * @name getURL
 * @description desc
 * @param {string} stId desc
 * @param {string} stKey desc
 * @param {string} stMkt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getURL = function(stId, stKey, stMkt) {
    var rtn = new Array();
    for (var i = 0; i < reqInf.length; i++) {
        if ((reqInf[i].id == stId) && (reqInf[i].mkt == stMkt)) {
            for (var j = 0; j < reqInf[i].def.length; j++) {
                rtn[j] = scwin.urlHdr + "&outputMessageId=" + reqInf[i].def[j].msgId + "&" + scwin.svcId + "&queryId=" + reqInf[i].def[j].qryId + "&" + scwin.urlFtr + stKey;
            }
            break;
        }
    }
    return rtn;
};
/**
 * @method
 * @name getURL2
 * @description desc
 * @param {string} stId desc
 * @param {string} stKey desc
 * @param {string} stMkt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getURL2 = function(stId, stKey, stMkt) {
    for (var i = 0; i < isuInf.length; i++) {
        if ((isuInf[i].id == stId) && (isuInf[i].mkt == stMkt)) {
            return scwin.urlHdr + "&outputMessageId=" + isuInf[i].msgId + "&" + scwin.svcId + "&queryId=" + reqInf[i].qryId + "&" + scwin.urlFtr + stKey;
        }
    }
};
/**
 * @method
 * @name invoke
 * @description desc
 * @param {string} arr desc
 * @param {string} mkt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.invoke = function(arr, mkt) {
    // 공시작성에 필요한 dataset 조회
    if (arr.length >= 3) {
        var urls = scwin.getURL(arr[0], arr[1], mkt); // arr[0]:서식코드, arr[1]:업무처리번호, arr[2]: 발행기관코드

        var dts = new Array();
        for (i = 0; i < urls.length; i++) {
            // 각 조회는 1건 이상이 될수도 있으며, dataset이 1개 이상이 될수도 있다.
            dts[i] = arr[i + 3];
            dts[i].DataID = urls[i];
            dts[i].reset();
        }
    }
};
/**
 * @method
 * @name invoke2
 * @description desc
 * @param {string} arr desc
 * @param {string} mkt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.invoke2 = function(arr, mkt) {
    // 공시전송시 공시종목(TBLD_DISCLS_ISU) 생성에 필요한 정보조회, 각 공시별로 관련 종목내역
    if (arr.length >= 3) {
        var urls = scwin.getURL2(arr[0], arr[1], mkt); // arr[0]:서식코드, arr[1]:업무처리번호, arr[2]: 발행기관코드, arr[3]: 종목정보를 포함할 dataset

        if (urls != "") {
            arr[3].DataID = urls;
            arr[3].reset();
        }
    }
};
